"use client"

/**
 * Profile & Settings Screen Prototype
 * ──────────────────────────────────────────────────────────────
 * Mobile profile + settings screen built entirely from Atlas
 * components and tokens: profile header, notification toggles,
 * appearance theme picker, and a confirm-guarded sign out.
 *
 * Route: /prototypes/settings
 */

import React, { useState } from "react"
import Link from "next/link"
import { PhoneFrame } from "../_shared/PhoneFrame"
import { Card, CardHeader, CardTitle, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"
import { Tabs } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
  DialogClose,
} from "@atlas/ui-web/compositions/Dialog/Dialog"

/* ── Types ─────────────────────────────────────────────────────── */

type Theme = "light" | "dark" | "system"

/* ── Icons ─────────────────────────────────────────────────────── */

const IconChevronLeft = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="15 18 9 12 15 6" />
  </svg>
)

const IconLogOut = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
    <polyline points="16 17 21 12 16 7" />
    <line x1="21" y1="12" x2="9" y2="12" />
  </svg>
)

/* ── Section wrapper ───────────────────────────────────────────── */

function SettingsSection({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <Card variant="outlined">
      <CardHeader>
        <CardTitle as="h2">{title}</CardTitle>
      </CardHeader>
      <CardContent>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "var(--atlas-spacing-4)",
          }}
        >
          {children}
        </div>
      </CardContent>
    </Card>
  )
}

/* ── Main screen ───────────────────────────────────────────────── */

function SettingsScreen() {
  const [pushEnabled, setPushEnabled] = useState(true)
  const [emailEnabled, setEmailEnabled] = useState(true)
  const [smsEnabled, setSmsEnabled] = useState(false)
  const [theme, setTheme] = useState<Theme>("system")
  const [signOutOpen, setSignOutOpen] = useState(false)

  const name = "Amara Bello"
  const email = "amara.bello@example.com"
  const initials = "AB"

  return (
    <div
      style={{
        flex: 1,
        display: "flex",
        flexDirection: "column",
        minHeight: 0,
        background: "var(--atlas-background)",
      }}
    >
      {/* ── Header bar ── */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--atlas-spacing-2)",
          padding: "var(--atlas-spacing-3) var(--atlas-spacing-4)",
          borderBottom: "1px solid var(--atlas-border)",
        }}
      >
        <button
          type="button"
          aria-label="Back"
          style={{
            width: "var(--atlas-touch-min)",
            height: "var(--atlas-touch-min)",
            marginInlineStart: "calc(var(--atlas-spacing-2) * -1)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: "none",
            border: "none",
            borderRadius: "var(--atlas-radius-full)",
            color: "var(--atlas-foreground)",
            cursor: "pointer",
          }}
        >
          <IconChevronLeft />
        </button>
        <h1
          style={{
            margin: 0,
            fontSize: "var(--atlas-font-size-lg)",
            fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
            color: "var(--atlas-foreground)",
          }}
        >
          Profile &amp; Settings
        </h1>
      </div>

      {/* ── Scrollable content ── */}
      <div
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "var(--atlas-spacing-4)",
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-5)",
        }}
      >
        {/* ── Profile header ── */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: "var(--atlas-spacing-3)",
            padding: "var(--atlas-spacing-4) 0 var(--atlas-spacing-2)",
          }}
        >
          <div
            style={{
              width: 72,
              height: 72,
              borderRadius: "var(--atlas-radius-full)",
              background: "var(--atlas-background-muted)",
              border: "1.5px solid var(--atlas-border)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "var(--atlas-font-size-xl)",
              fontWeight: "var(--atlas-font-weight-bold)" as React.CSSProperties["fontWeight"],
              color: "var(--atlas-foreground)",
              letterSpacing: "var(--atlas-letter-spacing-wide)",
            }}
            role="img"
            aria-label={`${name} avatar`}
          >
            {initials}
          </div>
          <div style={{ textAlign: "center" }}>
            <div
              style={{
                fontSize: "var(--atlas-font-size-lg)",
                fontWeight: "var(--atlas-font-weight-semibold)" as React.CSSProperties["fontWeight"],
                color: "var(--atlas-foreground)",
                lineHeight: "var(--atlas-line-height-tight)",
              }}
            >
              {name}
            </div>
            <div
              style={{
                fontSize: "var(--atlas-font-size-sm)",
                color: "var(--atlas-foreground-muted)",
                marginTop: "var(--atlas-spacing-0_5)",
              }}
            >
              {email}
            </div>
          </div>
        </div>

        {/* ── Notifications group ── */}
        <SettingsSection title="Notifications">
          <Switch
            label="Push notifications"
            description="Get real-time alerts on this device"
            checked={pushEnabled}
            onCheckedChange={setPushEnabled}
          />
          <Switch
            label="Email notifications"
            description="Receive updates and summaries by email"
            checked={emailEnabled}
            onCheckedChange={setEmailEnabled}
          />
          <Switch
            label="SMS notifications"
            description="Get text messages for critical account activity"
            checked={smsEnabled}
            onCheckedChange={setSmsEnabled}
          />
        </SettingsSection>

        {/* ── Appearance group ── */}
        <SettingsSection title="Appearance">
          <div>
            <div
              style={{
                fontSize: "var(--atlas-font-size-sm)",
                fontWeight: "var(--atlas-font-weight-medium)" as React.CSSProperties["fontWeight"],
                color: "var(--atlas-foreground)",
                marginBottom: "var(--atlas-spacing-2)",
              }}
            >
              Theme
            </div>
            <Tabs
              variant="pills"
              size="sm"
              value={theme}
              onValueChange={(v) => setTheme(v as Theme)}
              items={[
                { id: "light", label: "Light", content: null },
                { id: "dark", label: "Dark", content: null },
                { id: "system", label: "System", content: null },
              ]}
            />
          </div>
        </SettingsSection>

        {/* ── Sign out ── */}
        <Dialog open={signOutOpen} onOpenChange={setSignOutOpen}>
          <DialogTrigger asChild>
            <Button
              variant="destructive"
              leadingIcon={<IconLogOut />}
              style={{ width: "100%" }}
            >
              Sign out
            </Button>
          </DialogTrigger>
          <DialogContent size="sm">
            <DialogHeader>
              <DialogTitle>Sign out?</DialogTitle>
              <DialogDescription>
                You&apos;ll need to sign back in to access your account on this device.
              </DialogDescription>
            </DialogHeader>
            <DialogBody />
            <DialogFooter>
              <DialogClose asChild>
                <Button variant="outline">Cancel</Button>
              </DialogClose>
              <Button
                variant="destructive"
                onClick={() => setSignOutOpen(false)}
              >
                Sign out
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </div>
  )
}

/* ── Page ──────────────────────────────────────────────────────── */

export default function SettingsPrototype() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--atlas-background-muted)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: "var(--atlas-spacing-6) var(--atlas-spacing-4)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <div style={{ width: "100%", maxWidth: 390, marginBottom: "var(--atlas-spacing-3)" }}>
        <Link
          href="/prototypes"
          style={{
            fontSize: "var(--atlas-font-size-sm)",
            color: "var(--atlas-foreground-muted)",
            textDecoration: "none",
          }}
        >
          ← Prototypes
        </Link>
      </div>

      <PhoneFrame>
        <SettingsScreen />
      </PhoneFrame>
    </div>
  )
}

